public void insert()
{
    if (!this.TransactionNumber)
    {
        this.fillTransactionNumber();
    }

    super();
}

public void adjustLeaveBalance()
{
    ttsbegin;
    LeaveBankTransaction leaveBankTransaction;
    leaveBankTransaction.clear();

    leaveBankTransaction.Worker             = this.Worker;;
    leaveBankTransaction.LeavePlan          = this.LeavePlan;
    leaveBankTransaction.LeaveType          = this.LeaveType;
    leaveBankTransaction.TransactionDate    = this.TransactionDate;
    leaveBankTransaction.TransactionType    = LeaveTransactionType::BalanceAdjustment;
    leaveBankTransaction.Amount             = this.Amount;
    leaveBankTransaction.NVLeaveCategory    = NVLeaveCategory::FlightHours;
    leaveBankTransaction.Comment            = "Pilot addition leaves granted";

    leaveBankTransaction.insert();
    ttscommit;
}

private void fillTransactionNumber()
{
    this.TransactionNumber = NVPilotAdditionalLeaveTransaction::lastTransactionNumber(
        this.Worker,
        this.LeaveType,
        this.TransactionDate,
        this.TransactionType) + 1;
}

public static LineNum lastTransactionNumber(
    HcmWorkerRecId _workerRecId,
    LeaveTypeRecId _leaveTypeRecId,
    LeaveDate _trxDate,
    LeaveTransactionType _trxType)
{
    NVPilotAdditionalLeaveTransaction leaveTransaction;

    select firstonly TransactionNumber from leaveTransaction
        order by leaveTransaction.TransactionNumber desc
                where leaveTransaction.Worker == _workerRecId
                && leaveTransaction.LeaveType == _leaveTypeRecId
                && leaveTransaction.TransactionDate == _trxDate
                && leaveTransaction.TransactionType == _trxType;

    return leaveTransaction.TransactionNumber;
}

public static Amount totalGrantCurrentYear(HcmWorkerRecId _worker)
{
    FromDate currentYearStartDate = mkDate(1, 1, Year(today()));

    NVPilotAdditionalLeaveTransaction leaveTransaction;

    select sum(Amount) from leaveTransaction
        where leaveTransaction.Worker           == _worker
            && leaveTransaction.TransactionType == LeaveTransactionType::Grant
            && leaveTransaction.TransactionDate >= currentYearStartDate;

    return leaveTransaction.Amount;
}

public static Amount totalBalanceCurrentYear(HcmWorkerRecId _worker, LeaveTypeRecId _leaveType = 0)
{
    FromDate currentYearStartDate = mkDate(1, 1, Year(today()));

    NVPilotAdditionalLeaveTransaction leaveTransaction;

    select sum(Amount) from leaveTransaction
        where leaveTransaction.Worker           == _worker
            && leaveTransaction.TransactionDate >= currentYearStartDate
            && (_leaveType == 0 || leaveTransaction.LeaveType == _leaveType);

    return leaveTransaction.Amount;
}

public static Amount totalBalanceDateYear(HcmWorkerRecId _worker, LeaveTypeRecId _leaveType = 0, TransDate _date = today())
{
    FromDate yearStartDate = mkDate(1, 1, Year(_date));

    NVPilotAdditionalLeaveTransaction leaveTransaction;

    select sum(Amount) from leaveTransaction
        where leaveTransaction.Worker           == _worker
            && leaveTransaction.TransactionDate >= yearStartDate
            && (_leaveType == 0 || leaveTransaction.LeaveType == _leaveType);

    return leaveTransaction.Amount;
}

public static void insertRequest(LeaveBankTransaction _leaveBankTransaction, Amount _consumedLeave)
{
    NVPilotAdditionalLeaveTransaction additionalLeaveTransaction;

    additionalLeaveTransaction.Amount               = _consumedLeave;
    additionalLeaveTransaction.Worker               = _leaveBankTransaction.Worker;
    additionalLeaveTransaction.LeavePlan            = _leaveBankTransaction.LeavePlan;
    additionalLeaveTransaction.LeaveType            = _leaveBankTransaction.LeaveType;
    additionalLeaveTransaction.TransactionDate      = _leaveBankTransaction.TransactionDate;
    additionalLeaveTransaction.TransactionType      = _leaveBankTransaction.TransactionType;
    additionalLeaveTransaction.LeaveBankTransaction = _leaveBankTransaction.RecId;

    additionalLeaveTransaction.insert();
}
